//! `.ppk` files generated by PuTTYgen 0.83 (see `keys/ppk` in the testkit):
//! versions 2 and 3, encrypted and not, Ed25519, ECDSA and RSA.

use rooste_keys::{KeyError, PublicKey, load, ppk};
use rooste_testkit::{TEST_KEY_PASSPHRASE, key_path};

fn fixture(name: &str) -> (String, PublicKey) {
    let dir = key_path("ppk");
    let ppk = std::fs::read_to_string(dir.join(format!("{name}.ppk"))).unwrap();
    let public = std::fs::read_to_string(dir.join(format!("{name}.pub"))).unwrap();
    (ppk, PublicKey::from_openssh(public.trim()).unwrap())
}

#[test]
fn imports_every_puttygen_fixture() {
    for name in [
        "v3-ed25519",
        "v3-rsa",
        "v2-rsa",
        "v3-ed25519-encrypted",
        "v3-ecdsa-encrypted",
        "v2-ed25519-encrypted",
    ] {
        let (text, expected) = fixture(name);
        let encrypted = name.ends_with("encrypted");
        assert_eq!(ppk::is_encrypted(&text), encrypted, "{name}");
        let passphrase = encrypted.then_some(TEST_KEY_PASSPHRASE);
        let key = load(&text, passphrase).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(key.public_key().key_data(), expected.key_data(), "{name}");
        assert_eq!(
            key.comment().as_str_lossy(),
            format!("fixture-{name}"),
            "{name}"
        );
        if encrypted {
            assert!(
                matches!(load(&text, None), Err(KeyError::Encrypted)),
                "{name}"
            );
            assert!(
                matches!(load(&text, Some("wrong")), Err(KeyError::BadPassphrase)),
                "{name}"
            );
        }
    }
}

#[test]
fn reexported_keys_import_again() {
    for name in ["v3-rsa", "v2-ed25519-encrypted", "v3-ecdsa-encrypted"] {
        let (text, expected) = fixture(name);
        let key = load(&text, Some(TEST_KEY_PASSPHRASE)).unwrap();
        for passphrase in [None, Some("new secret")] {
            let exported = ppk::export(&key, passphrase).unwrap();
            let back = load(&exported, passphrase).unwrap();
            assert_eq!(back.public_key().key_data(), expected.key_data(), "{name}");
        }
    }
}

#[test]
fn ssh_layer_loads_ppk_and_asks_for_passphrases() {
    use rooste_protocols::ssh::{SshError, load_private_key};
    let dir = key_path("ppk");
    assert!(load_private_key(&dir.join("v3-ed25519.ppk"), None).is_ok());
    let encrypted = dir.join("v3-ed25519-encrypted.ppk");
    let result = load_private_key(&encrypted, None);
    assert!(
        matches!(result, Err(SshError::KeyEncrypted(_))),
        "{result:?}"
    );
    assert!(load_private_key(&encrypted, Some(TEST_KEY_PASSPHRASE)).is_ok());
}

/// Writes exported keys to `$ROOSTE_PPK_EXPORT_DIR` so they can be checked
/// with the real PuTTYgen (`puttygen file.ppk -L`).
#[test]
#[ignore = "manual check with PuTTYgen"]
fn export_for_puttygen() {
    let Some(dir) = std::env::var_os("ROOSTE_PPK_EXPORT_DIR").map(std::path::PathBuf::from) else {
        eprintln!("set ROOSTE_PPK_EXPORT_DIR to export keys for PuTTYgen");
        return;
    };
    for (name, kind) in [
        ("ed25519", rooste_keys::KeyType::Ed25519),
        ("ecdsa", rooste_keys::KeyType::EcdsaP256),
    ] {
        let key = rooste_keys::generate(kind, &format!("exported-{name}")).unwrap();
        for (suffix, passphrase) in [("plain", None), ("encrypted", Some("rooste"))] {
            let text = ppk::export(&key, passphrase).unwrap();
            std::fs::write(dir.join(format!("{name}-{suffix}.ppk")), text).unwrap();
        }
        std::fs::write(
            dir.join(format!("{name}.pub")),
            rooste_keys::public_line(key.public_key()),
        )
        .unwrap();
    }
    let (text, _) = fixture("v3-rsa");
    let rsa = load(&text, None).unwrap();
    std::fs::write(
        dir.join("rsa-encrypted.ppk"),
        ppk::export(&rsa, Some("rooste")).unwrap(),
    )
    .unwrap();
    std::fs::write(
        dir.join("rsa.pub"),
        rooste_keys::public_line(rsa.public_key()),
    )
    .unwrap();
}
